import { addDays, dateKey, fromKey } from './calendar';
import { FLAGS } from './flags';
import { generateProgram } from './generator';
import { setupFromProgram } from './homeV3';
import { sourceOf } from './source';
import type { Program } from './types';

/**
 * 2.4.1 R-5 (generator-v3-rulings.md; spec A6): switching existing programs to v3.
 *  - Never regenerate a program mid-block. An Approach-generated 2.3.0 program (no `block`, every lift session 'approach')
 *    keeps running until its current 4-week block ends; the next block is generated by v3 from the same inputs.
 *  - Coach-built programs (any session 'coach'), trainer programs and v3 programs are never touched.
 *  - Which generator made a block is derived from the program JSON: v3 programs carry `block` (no new key).
 * The message "Your next block uses Approach Strength's new programming." (Legal's 2.4.1 wording) is shown once per device.
 */
export const NEXT_BLOCK_LINE = "Your next block uses Approach Strength's new programming.";

const WEEKS = (p: Program) => p.blockWeeks ?? 4;

/** The first day of the block running on `today`, if the program's first block has ended (else null). */
function nextBlockStart(p: Program, today: Date): Date | null {
  const start = fromKey(p.blockStart ?? p.createdAt.slice(0, 10));
  const days = Math.floor((fromKey(dateKey(today)).getTime() - start.getTime()) / 864e5);
  const len = WEEKS(p) * 7;
  if (days < len) return null;
  return addDays(start, Math.floor(days / len) * len);
}

/** A 2.3.0 Approach-generated program whose current block has ended. */
export function needsV3Rollover(p: Program, today: Date = new Date()): boolean {
  if (!FLAGS.generatorV3 || p.block || p.general) return false;
  const lifts = p.sessions.filter((s) => !s.mobility);
  if (!lifts.length || lifts.some((s) => sourceOf(p, s) !== 'approach')) return false;
  return !!nextBlockStart(p, today);
}

/** The v3 program for the next block, keeping the program's identity, team, calendar and the coach's chosen rest days. */
export function rolloverV3(p: Program, today: Date = new Date()): Program {
  const start = nextBlockStart(p, today) ?? fromKey(dateKey(today));
  const kinds = setupFromProgram(p);
  const team = !!p.teamId;
  const fresh = generateProgram({
    name: p.name,
    forName: p.forName,
    author: p.author,
    position: p.position,
    phase: p.phase,
    experience: p.experience,
    volleyballWeek: p.volleyballWeek,
    liftDaysPerWeek: kinds.filter((k) => k === 'room' || k === 'home').length || 1,
    ...(team && (p.weightRoomDays?.length || kinds.includes('home') || kinds.includes('mobility'))
      ? { kinds }
      : { liftDays: kinds.map((k, i) => (k === 'room' ? i : -1)).filter((i) => i >= 0) }),
    equipment: p.equipment,
    homeJumps: p.homeJumps,
    ...(p.supersets != null ? { supersets: p.supersets } : {}),
  });
  const overrides = Object.fromEntries(Object.entries(p.overrides ?? {}).filter(([, v]) => v === null));
  return {
    ...fresh,
    id: p.id,
    name: p.name,
    createdAt: p.createdAt,
    blockStart: dateKey(start),
    teamId: p.teamId,
    teamName: p.teamName,
    groupKey: p.groupKey,
    groupName: p.groupName,
    postedAt: p.postedAt,
    events: p.events,
    overrides,
    lightDates: p.lightDates,
    customExercises: p.customExercises,
    sessionMinutes: p.sessionMinutes,
    minutesByWeekday: p.minutesByWeekday,
    levelAdjust: p.levelAdjust,
    levelAdjustOffFor: p.levelAdjustOffFor,
  };
}
